-(int) doSmithWatermanGotohFor: (char * )a ofLength: (int) na and: (char *) b ofLength: (int) nb into: (int *) aa and: (int *) ba// a and b are 1-based arrays!{	int matrixSize = (na + 10) * (nb + 10) * sizeof(int);	// Use data structures instead of ordinary C arrays in order to take advantage of garbage collection	NSMutableData * vData = [NSMutableData dataWithLength:matrixSize]; // match score	NSMutableData * eData = [NSMutableData dataWithLength:matrixSize]; // deletions	NSMutableData * fData = [NSMutableData dataWithLength:matrixSize];  // insertions	NSMutableData * btData = [NSMutableData dataWithLength:matrixSize]; // bt = backtrace	NSMutableData * btFData = [NSMutableData dataWithLength:matrixSize]; // bt = backtrace	NSMutableData * btEData = [NSMutableData dataWithLength:matrixSize]; // bt = backtrace	int  * v = [vData mutableBytes];	int * e = [eData mutableBytes];	int * f = [fData mutableBytes];	int * bt = [btData mutableBytes];	int * btE = [btEData mutableBytes];	int * btF = [btFData mutableBytes];		// initialize arrays	int ij, i,j=0, rowsize = nb+1;	for (i = 0; i <= na; i++) {		ij = i * rowsize + j;		v[ij] = 0;		e[ij] = 0;		f[ij] = 0;	}	i=0;	for(j = 0; j <= nb; j++) {		ij = i * rowsize + j;		v[ij] = 0;		e[ij] = 0;		f[ij] = 0;	}		// build v,e, f and bt arrays	int matchval;	int ee, ev, ff, fv;  // to keep track of where each e or f came from.	int vtemp, etemp, ftemp, vbest;	for (i = 1; i <= na; i++) {		for (j = 1; j <= nb; j++) {			ij = i * rowsize + j;						ev = v[dex(i,j-1)] + delOpen;			ee = e[dex(i,j-1)] + delCont;			if (ev > ee) {				e[ij] = ev;				btE[ij] = j-1;			} else {				e[ij] = ee;				btE[ij] = btE[dex(i,j-1)];			}								 			fv = v[dex(i-1,j)] + insOpen;			ff = f[dex(i-1,j)] + insCont;			if (fv > ff) {				f[ij] = fv;				btF[ij] = i-1;			} else {				f[ij] = ff;				btF[ij] = btF[dex(i-1,j)];			}								 						matchval = (a[i]==b[j]) ? match: mismatch;			if ((a[i]==enChar) || (b[i]==enChar)) {				matchval = ambiguity;			}						vtemp = v[dex(i-1, j-1)] + matchval;			ftemp = f[ij];			etemp = e[ij];						if (vtemp >= max(etemp, ftemp)) {				vbest = vtemp;				bt[ij] = 0;			} else if				(ftemp >= max(vtemp, etemp)) {					vbest = ftemp;					bt[ij] = -1;				} else {					vbest = etemp;					bt[ij] = 1;				}				if (vbest < 0) vbest = 0;			v[ij] = vbest;		}	}		// find cell with maximum value	int imax=1, jmax=1, vmax = 0;	for(i = 1; i <= na; i++) {		for (j = 1; j <= nb; j++) {			ij = i * rowsize + j;			if (v[ij] > vmax) {				vmax = v[ij];				imax = i;				jmax = j;			}//if		}// for j	}// for i	// backtrace	i=imax; j=jmax;	int k=imax + jmax + 2;	int pointer, newpointer,iTarget = 10000, jTarget= 10000, matchlength = 1;	while (v[i*rowsize + j] > 0) {		aa[k] = i;		ba[k] = j;		newpointer = bt[i * rowsize + j];		if (pointer ==0 && newpointer == -1) {			iTarget = btF[i*rowsize + j];		}		if (pointer == 0 && newpointer == 1) {			jTarget = btE[i*rowsize + j];		}		if (i <= iTarget && j <= jTarget) pointer = newpointer; 				if (i > iTarget) pointer = -1;		if (j > jTarget) pointer = 1;				if (pointer <1) i--;		if (pointer >-1) j--;		k--;		matchlength++;	}		// trim aa and ba	while (!aa[1]) aa++;	while (!ba[1]) ba++; // Display arrays for debugging purposes//	[self showArray:v withDimensions:na and:nb];//	[self showArray:btE withDimensions:na and:nb];//	[self showArray:btF withDimensions:na and:nb];//	[self showArray:bt withDimensions:na and:nb];		return vmax;}  // end of Smith-Waterman-Gotoh routine-(char) matcher: (char) a : (char) b{	if(a == spaceChar || b == spaceChar) return spaceChar;	if(a == hyphenChar || b == hyphenChar) return spaceChar;	if(a == enChar || b == enChar) return ambChar;	if(a == b) return matchChar;	return spaceChar;}-(char) complement: (char) a{	switch (a) {		case aChar:	return tChar;		case cChar: return gChar;		case tChar: return aChar;		case gChar: return cChar;		default: return enChar;	}}-(void) main{	njoin = [joinString length];	nright = [rightString length];	nleft = [leftString length];	joinData = [[joinString uppercaseString] dataUsingEncoding:NSUTF8StringEncoding];	leftData = [[leftString uppercaseString] dataUsingEncoding:NSUTF8StringEncoding];	rightData = [[rightString uppercaseString] dataUsingEncoding:NSUTF8StringEncoding];	join = (char *)[joinData bytes]; join --; // makes a one-based array	left = (char *)[leftData bytes]; left --;	right = (char *)[rightData bytes]; right --;		joinrightData = [NSMutableData dataWithLength:(njoin + nright + 3) * sizeof(int) ];	rightjoinData = [NSMutableData dataWithLength:(njoin + nright + 3) * sizeof(int) ];	joinleftData = [NSMutableData dataWithLength:(njoin + nleft + 3) * sizeof(int) ];	leftjoinData = [NSMutableData dataWithLength:(njoin + nleft + 3) * sizeof(int) ];	jr = [joinrightData mutableBytes]; jr--;	rj = [rightjoinData mutableBytes]; rj--;	jl = [joinleftData mutableBytes]; jl--;	lj = [leftjoinData mutableBytes]; lj--;		[self doSmithWatermanGotohFor:join ofLength:njoin and:left ofLength:nleft into: jl and: lj];		// trim 	while (!jl[1]) jl++;	while (!lj[1]) lj++;	jllength = 1;  while (jl[jllength++]);jllength--;	ljlength = 1; while (lj[ljlength++]);ljlength--;		[self doSmithWatermanGotohFor:join ofLength:njoin and:right ofLength:nright into: jr and: rj];	// trim 	while (!jr[1]) jr++;	while (!rj[1]) rj++;	jrlength = 1; while(jr[jrlength++]);jrlength--;	rjlength = 1; while(rj[rjlength++]);rjlength--;		int i,j,k;		// Convert gaps to -1	for (i=jllength; i >1; i--) {		if (jl[i] == jl[i-1]) jl[i] = -1;		if (lj[i] == lj[i-1]) lj[i] = -1;	}	for (i = jrlength; i > 1; i--) {		if (jr[i] == jr[i-1]) jr[i] = -1;		if (rj[i] == rj[i-1]) rj[i] = -1;	}		NSString * fmat = @"%3d";// display numerical alignments#if SHOWNUMS == 1	{	NSMutableString * out = [NSMutableString stringWithFormat:@"alignment %@\rjoin-left : ", [maker jname]];	for (i = 1; i < jllength; i++) [out appendFormat:fmat, jl[i]];	[out appendFormat:@"\rleft-join : "];	for (i = 1; i < ljlength; i++) [out appendFormat:fmat, lj[i]];	[out appendFormat:@"\r\rjoin-right: "];	for (i = 1; i < jrlength; i++) [out appendFormat:fmat, jr[i]];	[out appendFormat:@"\rright-join: "];	for (i = 1; i < rjlength; i++) [out appendFormat:fmat, rj[i]];	[out appendFormat:@"\r\r"];	[myDoc appendOutput: out];				return;	}#endif		// Construct array of triplets	NJtriplet * newt, *oldt;	tripArray = [NSMutableArray arrayWithCapacity:jllength + jrlength];	for (i = 1; i < jllength; i++) {		newt = [NJtriplet new];		[newt initWithTop:lj[i] mid:jl[i] bot:0 maker:self];		[tripArray addObject:newt];	}	int lastJ = newt.mid;	NSRange fillerRange = NSMakeRange(min(newt.top, newt.mid), 0);	while (lastJ < jr[1]-1) {  // there is some filler to add		newt = [NJtriplet new];		[newt initWithTop:0 mid:++lastJ bot:0 maker:self];		[tripArray addObject:newt];		fillerRange.length++;	}	j=1;	NSRange microRange = NSMakeRange(0, 0);	if (lastJ >= jr[1]) {  // there is microhomology		j = 1; i = 0;		k = [[tripArray objectAtIndex:i] mid];		while (jr[1] < k) {			//extra spaces have to be added in front of the tripArray list			newt = [NJtriplet new];			[newt initWithTop:0 mid:--k bot:0 maker:self];			[tripArray insertObject:newt atIndex:0];		}				// find i corresponding to j = 1		while ((jr[1] != [[tripArray objectAtIndex:i] mid]) && (i < tripArray.count - 1)) i++;		if ([[tripArray objectAtIndex:i] mid] != jr[1]) 		{  // Something has gone wrong -- maybe a bad match			k = [[tripArray objectAtIndex:i] mid];		}		microStart = i;		microRange.location = microStart;		if (i < jllength) while (jr[j] != lastJ + 1 && j < jrlength) {			if (i < tripArray.count) {				oldt = [tripArray objectAtIndex:i];			} else {				// create a new "old"				oldt = [NJtriplet new];				[oldt initWithTop:0 mid:-1 bot:0 maker:self];				[tripArray insertObject:oldt atIndex:i];			}			newt = [NJtriplet new];			[newt initWithTop:0 mid:jr[j] bot:rj[j] maker:self];									if (oldt.mid < 0 && newt.mid >0) {				oldt.bot = -1;				i++; // bypass							} else if (oldt.mid > 0 && newt.mid < 0) {				newt.top = -1;  // insert a new base with no match in left				[tripArray insertObject:newt atIndex:i];				jllength++;				i++; j++;			} else if (oldt.mid == newt.mid){				[oldt mergeWith:newt];				j++; i++;			} else {				i++;			}			microRange.length++;		}		//Trim microhomology if it ends in a gap		newt = [tripArray objectAtIndex:i-1];		newt = [tripArray objectAtIndex:i-2];		newt = [tripArray objectAtIndex:i-3];				while ([[tripArray objectAtIndex: --i] mid] < 0) microRange.length --;	}	while (j < jrlength) {  // now add on the rest of the right matches		newt = [NJtriplet new];		[newt initWithTop:0 mid:jr[j] bot:rj[j] maker:self];		[tripArray addObject:newt];		j++;	}		// fill in pointers to missing left bases	j = jllength -2;	lastJ	= [[tripArray objectAtIndex:j] top];	NSRange missingLeftRange = NSMakeRange(jllength-1, 0);//	while ((lastJ < nleft) && (nleft - lastJ < 30) && (j < tripArray.count -1)) {	while ((lastJ < nleft)  && (j < tripArray.count -1)) {		newt = [tripArray objectAtIndex:++j];		newt.top = ++lastJ;		missingLeftRange.length++;	}			// fill in pointers to missing right bases	j = [tripArray count] - jrlength;	j = 0;	while(![[tripArray objectAtIndex:j] bot]) j++;	lastJ = [[tripArray objectAtIndex:j] bot];	NSRange missingRightRange = NSMakeRange(j, 0);	while (lastJ > 1 && j > 0) {		newt = [tripArray objectAtIndex:--j];		newt.bot = --lastJ;		missingRightRange.location--;		missingRightRange.length++;	}		// get characters without uppercase		joinData = [joinString dataUsingEncoding:NSUTF8StringEncoding];	leftData = [leftString dataUsingEncoding:NSUTF8StringEncoding];	rightData = [rightString dataUsingEncoding:NSUTF8StringEncoding];	join = (char *)[joinData bytes]; join --; // makes a one-based array	left = (char *)[leftData bytes]; left --;	right = (char *)[rightData bytes]; right --;			// put characters into triplets	for (i = 0; i < tripArray.count; i++) {		newt = [tripArray objectAtIndex:i];		switch (newt.top) {			case 0:				newt.topChar = spaceChar;				break;			case -1:				newt.topChar = hyphenChar;				break;			default:				newt.topChar = left[newt.top];				break;		}			switch (newt.mid) {			case 0:				newt.midChar = spaceChar;				break;			case -1:				newt.midChar = hyphenChar;				break;			default:				newt.midChar = join[newt.mid];				break;		}		switch (newt.bot) {			case 0:				newt.botChar = spaceChar;				break;			case -1:				newt.botChar = hyphenChar;				break;			default:				newt.botChar = right[newt.bot];				break;		}	}		NSMutableData * tData, *mData, *bData;	tData = [NSMutableData dataWithLength:tripArray.count + 1];	mData = [NSMutableData dataWithLength:tripArray.count + 1];	bData = [NSMutableData dataWithLength:tripArray.count + 1];	char * t = [tData mutableBytes];	char * m = [mData mutableBytes];	char * b = [bData mutableBytes];	for (i = 0; i < tripArray.count; i++) {		newt = [tripArray objectAtIndex: i];		t[i] = newt.topChar;		m[i] = newt.midChar;		b[i] = newt.botChar;	}			// put results into maker (NJoin)	maker.microRange = microRange;	maker.missingRightRange = missingRightRange;	maker.missingLeftRange = missingLeftRange;	maker.fillerRange = fillerRange;		// display the completed triplet list	NSMutableString * topout, *midout, *botout;	topout = [@"\rleft:  " mutableCopy];	midout = [@"\rjoin:  " mutableCopy];	botout = [@"\rright: " mutableCopy];	for (newt in tripArray) {		[topout appendFormat:fmat, newt.top];		[midout appendFormat:fmat, newt.mid];		[botout appendFormat:fmat, newt.bot];	}		NSString * topString = [NSString stringWithUTF8String:t];	NSString * midString = [NSString stringWithUTF8String:m];	NSString * botString = [NSString stringWithUTF8String:b];		NSRange leftOverhangRange = NSMakeRange(0, 0), rightOverhangRange = NSMakeRange(0, 0);	NSString * overhangString = [[myDoc overhang] uppercaseString];	if(overhangString.length > 0) {		leftOverhangRange = [[topString uppercaseString] rangeOfString:overhangString options: NSBackwardsSearch];		rightOverhangRange = [[botString uppercaseString] rangeOfString:overhangString];		if(leftOverhangRange.location == NSNotFound) leftOverhangRange.location = 0;		if(rightOverhangRange.location == NSNotFound) rightOverhangRange.location = 0;	}		maker.rightOverhangRange = rightOverhangRange;	maker.leftOverhangRange = leftOverhangRange;	//	[myDoc appendOutput:[NSString stringWithFormat:@"\r%@\r%@\r%@\r", topString, midString, botString]];	/*	[myDoc appendOutput:[NSString stringWithFormat:@"\rMicrohomology: %d, %d\rLeft missing: %d, %d\rRight missing: %d, %d\r\r", 						 microRange.location, microRange.length,						 missingLeftRange.location, missingLeftRange.length,						 missingRightRange.location, missingRightRange.length]];	 */		// make attributed strings		// Need a way to avoid trying to add attributes beyond the range of the string.	NSDictionary * userPrefs = [myDoc userPrefs];	NSMutableAttributedString * ss = [[NSMutableAttributedString alloc] initWithString: topString attributes: [userPrefs objectForKey:@"endFmat"]];	[ss addAttributes:[userPrefs objectForKey:@"overhangFmat"] range:leftOverhangRange];	[ss addAttributes:[userPrefs objectForKey:@"missingFmat"] range:missingLeftRange];	maker.topString = ss;//	[myDoc appendOutputA: ss];//	[myDoc appendOutput: [NSString stringWithFormat:@"\r"]];	[ss initWithString:midString attributes: [userPrefs objectForKey:@"joinFmat"]];	[ss addAttributes:[userPrefs objectForKey:@"microFmat"] range:microRange];	NSRange ssRange = NSMakeRange(0, ss.length);	NSRange ssintersect = NSIntersectionRange(ssRange, fillerRange);	[ss addAttributes:[userPrefs objectForKey:@"fillerFmat"] range:ssintersect];	maker.midString = ss;//	[myDoc appendOutputA: ss];//	[myDoc appendOutput: [NSString stringWithFormat:@"\r"]];	[ss initWithString:botString attributes: [userPrefs objectForKey:@"endFmat"]];	[ss addAttributes:[userPrefs objectForKey:@"overhangFmat"] range:rightOverhangRange];	[ss addAttributes:[userPrefs objectForKey:@"missingFmat"] range:missingRightRange];	maker.botString = ss;//	[myDoc appendOutputA: ss];//	[myDoc appendOutput: [NSString stringWithFormat:@"\r"]];		// make match strings;	NSString * topUC = [topString uppercaseString];	NSString * midUC = [midString uppercaseString];	NSString * botUC = [botString uppercaseString];	char ctop, cmid, cbot;			NSMutableData * mtData = [NSMutableData dataWithLength:tripArray.count + 1];	NSMutableData * mbData = [NSMutableData dataWithLength:tripArray.count + 1];	char * mt = [mtData mutableBytes];	char * mb = [mbData mutableBytes];	for (i = 0; i < topUC.length; i++) {		ctop = [topUC characterAtIndex:i];		cmid = [midUC characterAtIndex:i];		cbot = [botUC characterAtIndex:i];		mt[i] = [self matcher:ctop :cmid];		mb[i] = [self matcher:cmid :cbot];	}	// ignore matches in missing areas	for (i = missingLeftRange.location; i < missingLeftRange.location + missingLeftRange.length; i++) mt[i] = spaceChar;	for (i = missingRightRange.location; i < missingRightRange.location + missingRightRange.length; i++) mb[i] = spaceChar;		// is microhomology perfect?	BOOL perfect = YES;	for(i = microRange.location; i < microRange.location + microRange.length; i++) {		if(mt[i] != matchChar || mb[i] != matchChar) perfect = NO;	}	if(microRange.length == 0) perfect = YES;  	maker.perfectMicro = ! perfect;		// is match complex:	BOOL complex = NO;	BOOL rightMatchesStarted = NO, leftMatchesStarted = NO, rightMatchesDone = NO, leftMatchesDone = NO;	for (i = 0; i < tripArray.count; i++) {		if(t[i] == hyphenChar || m[i] == hyphenChar || b[i] == hyphenChar) complex = YES;		// now make sure there is only a single run of matches/ambigs with each end;		if(leftMatchesDone && mt[i] == matchChar) complex = YES;		if(rightMatchesDone && mb[i] == matchChar) complex = YES;		if(mt[i] != spaceChar) leftMatchesStarted = YES;		if(mb[i] != spaceChar) rightMatchesStarted = YES;		if(leftMatchesStarted && mt[i] == spaceChar) leftMatchesDone = YES;		if(rightMatchesStarted && mb[i] == spaceChar) rightMatchesDone = YES;	}	maker.complexAlignment = complex;	// Look for a match with any longish filler	ss = [[NSMutableAttributedString alloc] initWithString:[NSString stringWithUTF8String:mt] attributes: [userPrefs objectForKey:@"endFmat"]];	maker.leftMatchString = ss;	ss = [[NSMutableAttributedString alloc] initWithString:[NSString stringWithUTF8String:mb] attributes: [userPrefs objectForKey:@"endFmat"]];	maker.rightMatchString = ss;		i = [[[myDoc userPrefs] objectForKey: @"minFillerLength"] intValue];		if (fillerRange.length >= [[[myDoc userPrefs] objectForKey: @"minFillerLength"] intValue]) {  // There is enough filler to be worth checking for matches.		BOOL weakMatch = NO;				// get the data to compare		NSString * originalString = [[[[myDoc originalSequence] string] uppercaseString] stringByReplacingOccurrencesOfString: @"^" withString: @""];		int originalLength = originalString.length;		NSMutableData * originalData = [NSMutableData dataWithLength:originalLength];		originalData = [[originalString dataUsingEncoding:NSUTF8StringEncoding] mutableCopy];		char * original = (char *)[originalData mutableBytes]; original--; // makes a one-based array				NSMutableData * fillerData = [NSMutableData dataWithLength:fillerRange.length +1];		char * fillerD = (char *) [fillerData mutableBytes]; fillerD--;		fillerRange = NSIntersectionRange(fillerRange, NSMakeRange(0, midUC.length));		for (i = 1; i <= fillerRange.length; i++) fillerD[i] = [midUC characterAtIndex:fillerRange.location + i - 1];		NSMutableData * fillerGData = [NSMutableData dataWithLength:fillerRange.length +1];		char * fillerG = (char *) [fillerGData mutableBytes]; fillerG--;		for (i = 1; i <= fillerRange.length; i++) fillerG[i] = [self complement:[midUC characterAtIndex:fillerRange.location + fillerRange.length - i]];				// now find best fits		int fitD, fitG;		NSMutableData * fitDaData = [NSMutableData dataWithLength:(fillerRange.length * originalLength + 3) * sizeof(int)];		NSMutableData * fitDbData = [NSMutableData dataWithLength:(fillerRange.length * originalLength + 3) * sizeof(int)];		NSMutableData * fitGaData = [NSMutableData dataWithLength:(fillerRange.length * originalLength + 3) * sizeof(int)];		NSMutableData * fitGbData = [NSMutableData dataWithLength:(fillerRange.length * originalLength + 3) * sizeof(int)];		// fitDa and fitGa are positions within original		// fitDb and fitGb are positions within D or G filler		int * fitDa = (int *)[fitDaData mutableBytes]; fitDa--;		int * fitDb = (int *)[fitDbData mutableBytes]; fitDb--;		int * fitGa = (int *)[fitGaData mutableBytes]; fitGa--;		int * fitGb = (int *)[fitGbData mutableBytes]; fitGb--;				fitD = [self doSmithWatermanGotohFor:original ofLength:originalLength and:fillerD ofLength:fillerRange.length into:fitDa and:fitDb];		fitG = [self doSmithWatermanGotohFor:original ofLength:originalLength and:fillerG ofLength:fillerRange.length into:fitGa and:fitGb];				double matchScore = max(fitD, fitG);		matchScore = matchScore * 100 / (fillerRange.length * match);		if (matchScore < [[[myDoc userPrefs] objectForKey: @"minFillerPercentMatch"] intValue]) {			weakMatch = YES;			// We should bail out of all this.		}//trim		while(!fitDa[1]) fitDa++;		while(!fitDb[1]) fitDb++;		while(!fitGa[1]) fitGa++;		while(!fitGb[1]) fitGb++;				// display numerical alignments#if SHOWNUMS == 2		{			NSMutableString * out = [NSMutableString stringWithFormat:@"alignment %@ v-score (D) = %d   vscore (G) = %d\r fitDa : ", [maker jname], fitD, fitG];			for (i = 1; i < originalLength; i++) [out appendFormat:fmat, fitDa[i]];			[out appendFormat:@"\r fitDb : "];			for (i = 1; i < originalLength; i++) [out appendFormat:fmat, fitDb[i]];			[out appendFormat:@"\r\r fitGa: "];			for (i = 1; i < originalLength; i++) [out appendFormat:fmat, fitGa[i]];			[out appendFormat:@"\r fitGb: "];			for (i = 1; i < originalLength; i++) [out appendFormat:fmat, fitGb[i]];			[out appendFormat:@"\r\r"];			[myDoc appendOutput: out];		}#endif				NSRange fillerMatchRange;		NSDictionary * fillerMatchFmat;		if (fitD >= fitG) {			i = 1;			while(fitDa[i++]);			 fillerMatchRange = NSMakeRange(fitDa[1]-1, fitDa[i-2] - fitDa[1] + 1);			maker.fillerTemplate = 1;			fillerMatchFmat = [[myDoc userPrefs] objectForKey:@"forwardTemplateFmat"];		} else {			i = 1;			while(fitGa[i++]);			fillerMatchRange = NSMakeRange(fitGa[1]-1, fitGa[i-2] - fitGa[1] + 1);			maker.fillerTemplate = 2;			fillerMatchFmat = [[myDoc userPrefs] objectForKey:@"reverseTemplateFmat"];		}		fillerMatchRange.length = min(fillerMatchRange.length, originalLength - fillerMatchRange.location);		fillerMatchRange = NSIntersectionRange(fillerMatchRange, NSMakeRange(0, [[[myDoc originalSequence] string] length]));		// find out how many carets there are  in the original string before fillerMatchRange.position and adjust position accordingly		NSString * prematch = [[[myDoc originalSequence] string] substringToIndex:fillerMatchRange.location + fillerMatchRange.length];		int caretcount = prematch.length - [[prematch stringByReplacingOccurrencesOfString: @"^" withString: @""] length];		fillerMatchRange.location += caretcount;				ss = [[myDoc originalSequence] mutableCopy];		NSDictionary * defaultAttributes = [NSDictionary dictionaryWithObject:[NSFont fontWithName:[[myDoc userPrefs] objectForKey:@"fontName"] size:[[[myDoc userPrefs] objectForKey:@"fontSize"] intValue]] forKey:NSFontAttributeName];				[ss addAttributes: defaultAttributes range: NSMakeRange(0, ss.length)];													[ss addAttributes:fillerMatchFmat range:fillerMatchRange];				if(! weakMatch) maker.fillerMatchString = ss;		if (weakMatch) maker.fillerTemplate = 0;			} else {		maker.fillerMatchString = [[NSMutableAttributedString alloc] initWithString:@""];		maker.fillerTemplate = 0;	}}#undef spaceChar#undef hyphenChar#undef ambChar#undef matchChar#undef enChar#undef aChar#undef cChar#undef gChar#undef tChar#undef dex#undef max#undef min#undef SHOWNUMS@end